// ===== Pas deze waarden aan je eigen omgeving aan (geen geheimen hier) =====
const cfg = {
  // HCP Terraform
  tfc_org: 'JOUW_HCP_ORGANISATIE',
  tfc_project_id: 'prj-VUL_IN',                 // project "labs"
  vcs_repo: 'JOUW_GITHUB_ORG/network-experience-2627-n8n',
  vcs_branch: 'main',
  vcs_oauth_token_id: 'ot-VUL_IN',              // HCP: Settings > Providers (VCS)
  tf_working_directory: 'ansible-terraform-agent/terraform',

  // E-mail
  mail_from: 'n8n-labs@school.example',
  approver_email: 'labbeheer@school.example',   // keurt aanmaken en opruimen goed
  admin_email: 'labbeheer@school.example',      // krijgt technische fouten

  // Proxmox-keuzes die de AI-agent mag maken
  allowed_nodes: ['pve1'],
  allowed_storages: ['local-lvm'],
  templates: { '9000': 'Debian 13 genericcloud met qemu-guest-agent' },
  // Vast, niet door de agent gekozen
  lab_bridge: 'vmbr1',
  lab_vlan: 120,                                // null = geen VLAN-tag

  // VMID-blokken: slot n = 5000 + n*50 .. +49 (laatste ID = docent-VM)
  vmid_base: 5000, vmids_per_lab: 50, max_slots: 20,
  max_students: 40,
  limits: { cpu: [1, 4], memory_mb: [512, 8192], disk_gb: [8, 100], total_memory_mb: 131072 },
  max_lab_days: 120,
  extend_days_on_reject: 7,

  // Moet overeenkomen met ansible/catalog.yml
  lab_roles: {
    lab_webserver: { description: 'nginx-webserver met testpagina; optioneel PHP-FPM', vars: { install_php: 'bool' } },
    lab_docker: { description: 'Docker Engine (docker.io); labgebruiker in groep docker', vars: {} },
  },

  // Polling van HCP-runs
  poll: { plan_seconds: 15, plan_max: 80, apply_seconds: 30, apply_max: 80 },
};
const input = $input.first().json;
const source = Object.prototype.hasOwnProperty.call(input, 'Klasgroep') ? 'aanvraag' : 'opruimen';
return [{ json: { ...input, cfg, source } }];

const { cfg, source, ...form } = $input.first().json;
const errors = [];
const s = (v) => (v == null ? '' : String(v)).trim();
const TEXT = /^[\p{L}\p{N} .,()+\-\/&'_]{1,80}$/u;
const SSH = /^(ssh-ed25519|ecdsa-sha2-nistp(256|384|521)|ssh-rsa) [A-Za-z0-9+/=]{20,8192}( [\x20-\x7e]{0,100})?$/;
const slug = (t) => t.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

const klasgroep = s(form['Klasgroep']);
const labnaam = s(form['Labnaam']);
const docent_email = s(form['E-mail docent']).toLowerCase();
const inhoud = s(form['Inhoud']).slice(0, 2000);
if (!TEXT.test(klasgroep) || klasgroep.length > 40) errors.push('Klasgroep: maximaal 40 tekens, letters/cijfers/spaties/-.');
if (!TEXT.test(labnaam)) errors.push('Labnaam: maximaal 80 tekens, letters/cijfers/spaties/-.');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(docent_email)) errors.push('E-mail docent is ongeldig.');
if (!inhoud) errors.push('Beschrijf wat er op de VM\'s moet staan.');

// Periode (tijdzone van de school)
const zone = 'Europe/Brussels';
const start = DateTime.fromISO(s(form['Startdatum']), { zone }).set({ hour: 8, minute: 0 });
const end = DateTime.fromISO(s(form['Einddatum']), { zone }).set({ hour: 20, minute: 0 });
if (!start.isValid || !end.isValid) errors.push('Start- of einddatum is ongeldig.');
else {
  if (end <= start) errors.push('De einddatum moet na de startdatum liggen.');
  if (end < DateTime.now()) errors.push('De einddatum ligt in het verleden.');
  if (end.diff(start, 'days').days > cfg.max_lab_days) errors.push(`Een labo duurt maximaal ${cfg.max_lab_days} dagen.`);
}

// Studentenlijst: deterministisch geparsed, NIET via de AI-agent
const students = [];
const seen = new Set();
s(form['Studenten']).split(/\r?\n/).map(l => l.trim()).filter(l => l && !l.startsWith('#')).forEach((line, i) => {
  const m = line.match(/^([A-Za-z][0-9]{7})\s*[;,\t ]\s*(.+)$/);
  if (!m) { errors.push(`Studenten, regel ${i + 1}: verwacht "r-nummer;ssh-public-key".`); return; }
  const id = m[1].toLowerCase();
  const key = m[2].trim();
  if (!SSH.test(key)) { errors.push(`Studenten, regel ${i + 1} (${id}): ongeldige publieke SSH-key.`); return; }
  if (seen.has(id)) { errors.push(`Studenten: ${id} staat meer dan eens in de lijst.`); return; }
  seen.add(id);
  students.push({ id, ssh_public_key: key });
});
if (students.length === 0) errors.push('Geef minstens één student op.');
if (students.length > cfg.max_students) errors.push(`Maximaal ${cfg.max_students} studenten per labo.`);

const teacherEnabled = s(form['Docent-VM']) === 'Ja';
const teacherKey = s(form['SSH-key docent']);
if (teacherEnabled && !SSH.test(teacherKey)) errors.push('Docent-VM gevraagd: geef een geldige publieke SSH-key van de docent.');

// lab_id: <klasgroep>-<labnaam>-<jaar>, maximaal 40 tekens
const year = start.isValid ? start.year : DateTime.now().year;
let lab_id = `${slug(klasgroep)}-${slug(labnaam)}-${year}`;
if (lab_id.length > 40) lab_id = `${slug(klasgroep).slice(0, 12)}-${slug(labnaam).slice(0, 21)}`.replace(/-+$/g, '') + `-${year}`;
if (!/^[a-z0-9][a-z0-9-]{2,38}[a-z0-9]$/.test(lab_id)) errors.push('Uit klasgroep en labnaam kon geen geldige lab-ID gemaakt worden.');

const request = {
  lab_id, klasgroep, labnaam, docent_email, inhoud,
  starts_at: start.isValid ? start.toISO() : null,
  ends_at: end.isValid ? end.toISO() : null,
  students,
  teacher_vm: { enabled: teacherEnabled, ssh_public_key: teacherEnabled ? teacherKey : '' },
};
return [{ json: { cfg, request, errors, valid: errors.length === 0 } }];

// Vertrouw het voorstel van de agent niet: alles wordt hier opnieuw gecontroleerd.
const { cfg, request } = $('Aanvraag voorbereiden').first().json;
let out = $input.first().json.output;
if (typeof out === 'string') { try { out = JSON.parse(out); } catch (e) { out = null; } }
const errors = [];
if (!out || typeof out !== 'object') errors.push('De AI-agent gaf geen bruikbaar voorstel.');
const p = (out && out.proxmox) || {};
const vp = (out && out.vm_profile) || {};
const inRange = (v, [a, b]) => Number.isInteger(v) && v >= a && v <= b;

if (!cfg.allowed_nodes.includes(p.node)) errors.push(`Node "${p.node}" is niet toegestaan.`);
if (!cfg.allowed_storages.includes(p.storage)) errors.push(`Storage "${p.storage}" is niet toegestaan.`);
const tpl = Number(p.template_vmid);
if (!Object.keys(cfg.templates).map(Number).includes(tpl)) errors.push(`Template ${p.template_vmid} is niet toegestaan.`);
const profile = { cpu: Number(vp.cpu), memory_mb: Number(vp.memory_mb), disk_gb: Number(vp.disk_gb) };
if (!inRange(profile.cpu, cfg.limits.cpu)) errors.push(`cpu ${vp.cpu} buiten ${cfg.limits.cpu.join('-')}.`);
if (!inRange(profile.memory_mb, cfg.limits.memory_mb)) errors.push(`memory_mb ${vp.memory_mb} buiten ${cfg.limits.memory_mb.join('-')}.`);
if (!inRange(profile.disk_gb, cfg.limits.disk_gb)) errors.push(`disk_gb ${vp.disk_gb} buiten ${cfg.limits.disk_gb.join('-')}.`);
const vmCount = request.students.length + (request.teacher_vm.enabled ? 1 : 0);
if (profile.memory_mb * vmCount > cfg.limits.total_memory_mb)
  errors.push(`Totaal geheugen ${profile.memory_mb * vmCount} MB is meer dan ${cfg.limits.total_memory_mb} MB.`);

const roles = Array.isArray(out && out.lab_roles) ? [...new Set(out.lab_roles)] : [];
for (const r of roles) if (!cfg.lab_roles[r]) errors.push(`Rol "${r}" staat niet in de catalogus.`);
const role_vars = {};
const rv = (out && out.role_vars && typeof out.role_vars === 'object') ? out.role_vars : {};
for (const [role, values] of Object.entries(rv)) {
  if (!roles.includes(role) || !values || typeof values !== 'object') continue;   // overbodige vars negeren
  for (const [k, v] of Object.entries(values)) {
    const type = cfg.lab_roles[role] && cfg.lab_roles[role].vars[k];
    const ok = (type === 'bool' && typeof v === 'boolean') || (type === 'int' && Number.isInteger(v)) || (type === 'str' && typeof v === 'string' && v.length <= 100);
    if (!ok) { errors.push(`Rolvariabele ${role}.${k} is niet toegestaan of heeft het verkeerde type.`); continue; }
    (role_vars[role] = role_vars[role] || {})[k] = v;
  }
}

const spec = {
  schema_version: 1,
  lab_id: request.lab_id, klasgroep: request.klasgroep, labnaam: request.labnaam, docent_email: request.docent_email,
  starts_at: request.starts_at, ends_at: request.ends_at,
  students: request.students, teacher_vm: request.teacher_vm,
  proxmox: { node: p.node, template_vmid: tpl, storage: p.storage, bridge: cfg.lab_bridge, vlan: cfg.lab_vlan, pool: `lab-${request.lab_id}` },
  vm_profile: profile,
  lab_roles: roles, role_vars,
  toelichting: String((out && out.toelichting) || '').slice(0, 1000),
};
return [{ json: { cfg, request, spec, errors, valid: errors.length === 0 } }];

const { cfg, spec } = $('Spec valideren').first().json;
let created = $input.first().json.created;
if (typeof created === 'string') created = JSON.parse(created);
const lab_id = spec.lab_id;
const vmidStart = cfg.vmid_base + created.vmid_slot * cfg.vmids_per_lab;

// Vaste volgorde: studenten gesorteerd op R-nummer -> s01, s02, ...; docent = laatste ID van het blok.
const sorted = [...spec.students].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
const vms = sorted.map((st, i) => ({
  key: 's' + String(i + 1).padStart(2, '0'), vmid: vmidStart + i, student_id: st.id, ssh_public_key: st.ssh_public_key,
}));
if (spec.teacher_vm.enabled) {
  vms.push({ key: 'docent', vmid: vmidStart + cfg.vmids_per_lab - 1, student_id: null, ssh_public_key: spec.teacher_vm.ssh_public_key });
}

// Terraform krijgt GEEN studentgegevens.
const terraformSpec = {
  schema_version: 1, lab_id,
  proxmox: spec.proxmox, vm_profile: spec.vm_profile,
  vms: vms.map(v => ({ key: v.key, vmid: v.vmid })),
};
const ansible_base = {
  lab_id, labnaam: spec.labnaam, klasgroep: spec.klasgroep, correlation_id: created.correlation_id,
  vms: vms.map(v => ({ key: v.key, name: `${lab_id}-${v.key}`, vmid: v.vmid, node: spec.proxmox.node, ssh_public_key: v.ssh_public_key })),
  lab_roles: spec.lab_roles, role_vars: spec.role_vars,
};
const n = vms.length;
return [{ json: {
  cfg, spec, lab_id, correlation_id: created.correlation_id,
  workspace_name: `lab-${lab_id}`,
  vms, vmid_range: `${vms[0].vmid}-${vms[n - 1].vmid}`,
  terraform_spec_json: JSON.stringify(terraformSpec),
  ansible_base,
  totals: { vms: n, cpu: n * spec.vm_profile.cpu, memory_mb: n * spec.vm_profile.memory_mb, disk_gb: n * spec.vm_profile.disk_gb },
} }];

// Doorzoekt MCP-uitvoer (content[].text, structuredContent, JSON in tekst) naar objecten.
function* walk(v, d = 0) {
  if (d > 14 || v == null) return;
  if (typeof v === 'string') {
    const s = v.trim();
    if (s.startsWith('{') || s.startsWith('[')) { try { yield* walk(JSON.parse(s), d + 1); } catch (e) {} }
    return;
  }
  if (Array.isArray(v)) { for (const c of v) yield* walk(c, d + 1); return; }
  if (typeof v === 'object') { yield v; for (const k of Object.keys(v)) yield* walk(v[k], d + 1); }
}
function findObj(v, pred) { for (const o of walk(v)) { try { if (pred(o)) return o; } catch (e) {} } return null; }
function mcpText(v) {
  const parts = [];
  for (const o of walk(v)) { if (o && o.type === 'text' && typeof o.text === 'string') parts.push(o.text); }
  return parts.join(' ').slice(0, 400);
}
function mcpIsError(v) { for (const o of walk(v)) { if (o && (o.isError === true || o.is_error === true)) return true; } return false; }

const all = $input.all().map(i => i.json);
const ws = findObj(all, o => o.type === 'workspaces' && typeof o.id === 'string' && o.id.startsWith('ws-'));
if (!ws) throw new Error('HCP-workspace niet gevonden na aanmaken: ' + mcpText(all));
return [{ json: { workspace_id: ws.id } }];

