const cfg = $('Configuratie').first().json.cfg;
const run = findObj($input.all().map(i => i.json), o => o.type === 'runs' && o.attributes && typeof o.attributes.status === 'string');
const status = run ? run.attributes.status : 'onbekend';
const planId = run && run.relationships && run.relationships.plan && run.relationships.plan.data ? run.relationships.plan.data.id : null;
const READY = ["planned", "cost_estimated", "policy_checked"];
const NOCHANGE = ["planned_and_finished"];
const FAILED = ['errored', 'discarded', 'canceled', 'force_canceled', 'policy_soft_failed'];
const poging = $runIndex + 1;
let fase = 'wachten';
let fout = null;
if (READY.includes(status)) fase = 'klaar';
else if (NOCHANGE.includes(status)) fase = 'geen_wijziging';
