const ctx = $('Lab voorbereiden').first().json;
const all = $input.all().map(i => i.json);
const plan = findObj(all, o => Array.isArray(o.resource_changes));
if (!plan) throw new Error('Plan-JSON niet gevonden: ' + mcpText(all));
const counts = { create: 0, update: 0, delete: 0 };
let vmCreates = 0;
for (const rc of plan.resource_changes) {
  const actions = (rc.change && rc.change.actions) || [];
  for (const a of actions) if (a in counts) counts[a]++;
  if (rc.type === 'proxmox_virtual_environment_vm' && actions.includes('create')) vmCreates++;
}
const problems = [];
if (counts.delete > 0) problems.push(`Het plan verwijdert ${counts.delete} resource(s).`);
if (counts.update > 0) problems.push(`Het plan wijzigt ${counts.update} bestaande resource(s).`);
if (vmCreates !== ctx.vms.length) problems.push(`Het plan maakt ${vmCreates} VM's aan, verwacht ${ctx.vms.length}.`);
const s = ctx.spec;
const summary = [
  `Labo:       ${s.labnaam} (${s.klasgroep})`,
  `Lab-ID:     ${ctx.lab_id}`,
  `Docent:     ${s.docent_email}`,
  `Periode:    ${s.starts_at} tot ${s.ends_at}`,
  `VM's:       ${ctx.totals.vms} (${s.students.length} studenten${s.teacher_vm.enabled ? ' + 1 docent' : ''})`,
  `Per VM:     ${s.vm_profile.cpu} vCPU, ${s.vm_profile.memory_mb} MB RAM, ${s.vm_profile.disk_gb} GB disk`,
  `Totaal:     ${ctx.totals.cpu} vCPU, ${ctx.totals.memory_mb} MB RAM, ${ctx.totals.disk_gb} GB disk`,
  `Proxmox:    node ${s.proxmox.node}, storage ${s.proxmox.storage}, template ${s.proxmox.template_vmid}, pool ${s.proxmox.pool}, VMID ${ctx.vmid_range}`,
  `Rollen:     ${s.lab_roles.join(', ') || '(alleen basis)'}`,
  `Terraform:  +${counts.create} ~${counts.update} -${counts.delete} (HCP-run ${$('Run-ID lezen').first().json.run_id})`,
  '',
  `Toelichting AI-agent: ${s.toelichting || '-'}`,
].join('\n');
return [{ json: { safe: problems.length === 0, problems, summary, counts } }];

